fn check_integer(text: &str) -> Option<bool> {
    let text = text.trim();
    if text.is_empty() {
        return None;
    }

    if text.chars().all(|ch| ch.is_ascii_digit()) {
        return Some(true);
    }

    let mut chars = text.chars();
    if let Some(first) = chars.next() {
        if (first == '+' || first == '-') && chars.clone().count() > 0 && chars.all(|ch| ch.is_ascii_digit()) {
            return Some(true);
        }
    }
    Some(false)
}

tests:
assert_eq!(check_integer("python"), Some(false));

assert_eq!(check_integer("1"), Some(true));

assert_eq!(check_integer("12345"), Some(true));
